CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE asset_status AS ENUM ('DRAFT','IN_STOCK','IN_USE','MAINTENANCE','RETIRED','LOST','ARCHIVED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE assignment_status AS ENUM ('ACTIVE','RETURNED','CANCELLED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE relation_type AS ENUM ('CONNECTED_TO','INSTALLED_IN','POWERED_BY','RECORDED_BY','PARENT_OF','ACCESSORY_OF'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_code text NOT NULL UNIQUE, category_id uuid NOT NULL, owner_company_id uuid NOT NULL, province_id uuid NOT NULL, site_id uuid NOT NULL, building_id uuid, floor_id uuid, room_id uuid, name text NOT NULL, brand text, model text, serial_number text, inventory_number text, status asset_status NOT NULL DEFAULT 'DRAFT', description text, from_ad boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), archived_at timestamptz);
CREATE INDEX IF NOT EXISTS assets_category_idx ON assets(category_id); CREATE INDEX IF NOT EXISTS assets_status_idx ON assets(status);
CREATE TABLE IF NOT EXISTS computer_details (asset_id uuid PRIMARY KEY REFERENCES assets(id) ON DELETE CASCADE, hostname text, operating_system text, ad_object_guid text UNIQUE, ad_distinguished_name text, last_ad_sync_at timestamptz);
CREATE TABLE IF NOT EXISTS mobile_details (asset_id uuid PRIMARY KEY REFERENCES assets(id) ON DELETE CASCADE, imei_1 text, imei_2 text, phone_number text, line_number text, operating_system text, user_changed_at timestamptz);
CREATE TABLE IF NOT EXISTS printer_details (asset_id uuid PRIMARY KEY REFERENCES assets(id) ON DELETE CASCADE, ip_address text, mac_address text, printer_name text, connection_type text, is_network_printer boolean NOT NULL DEFAULT false, room_id uuid);
CREATE TABLE IF NOT EXISTS network_details (asset_id uuid PRIMARY KEY REFERENCES assets(id) ON DELETE CASCADE, ip_address text, mac_address text, management_address text, hostname text, rack_id uuid, rack_unit integer CHECK(rack_unit IS NULL OR rack_unit BETWEEN 1 AND 100), upstream_asset_id uuid REFERENCES assets(id), installation_point text, responsible_profile_id uuid, notes text);
CREATE TABLE IF NOT EXISTS asset_code_sequences (site_id uuid NOT NULL, rack_id uuid NOT NULL, category_id uuid NOT NULL, next_value integer NOT NULL DEFAULT 1, PRIMARY KEY(site_id,rack_id,category_id));
CREATE TABLE IF NOT EXISTS asset_relations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_asset_id uuid NOT NULL REFERENCES assets(id) ON DELETE CASCADE, target_asset_id uuid NOT NULL REFERENCES assets(id) ON DELETE CASCADE, type relation_type NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_asset_id,target_asset_id,type), CHECK(source_asset_id<>target_asset_id));
CREATE TABLE IF NOT EXISTS assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES assets(id), profile_id uuid NOT NULL, assigned_by_user_id uuid NOT NULL, assigned_at timestamptz NOT NULL DEFAULT now(), returned_at timestamptz, received_by_user_id uuid, notes text, status assignment_status NOT NULL DEFAULT 'ACTIVE');
CREATE UNIQUE INDEX IF NOT EXISTS assignments_one_active_per_asset ON assignments(asset_id) WHERE status='ACTIVE'; CREATE INDEX IF NOT EXISTS assignments_profile_idx ON assignments(profile_id);
CREATE TABLE IF NOT EXISTS assignment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), assignment_id uuid NOT NULL REFERENCES assignments(id), action text NOT NULL, actor_id uuid NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS phone_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES assets(id), profile_id uuid, shared_room_id uuid, extension text, phone_number text, start_date date NOT NULL, end_date date, assigned_by_user_id uuid NOT NULL, notes text, is_primary boolean NOT NULL DEFAULT true, is_active boolean NOT NULL DEFAULT true, CHECK((profile_id IS NOT NULL)<>(shared_room_id IS NOT NULL)));
CREATE UNIQUE INDEX IF NOT EXISTS phone_users_one_active_primary_per_asset ON phone_users(asset_id) WHERE is_active=true AND is_primary=true;
CREATE TABLE IF NOT EXISTS asset_movements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES assets(id), type text NOT NULL, old_asset_code text, new_asset_code text, actor_id uuid NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS site_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, entity_type text NOT NULL, entity_id text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS site_audit_created_idx ON site_audit_logs(created_at);
